<?php namespace App\Http\Controllers\Account; use App\Http\Controllers\Controller; use App\Models\{Address,Order,ReturnRequest,RewardTransaction,Wishlist}; use Illuminate\Http\Request; use Illuminate\Support\Str;
class AccountController extends Controller { public function dashboard(){return view('site.account',['orders'=>auth()->user()->orders()->with('items')->latest()->limit(8)->get(),'rewards'=>auth()->user()->rewards()->sum('points'),'wishlistCount'=>auth()->user()->wishlistItems()->count()]);} public function section(string $section){$allowed=['orders','wishlist','rewards','addresses','profile','payments','designs','bulk-orders','returns'];abort_unless(in_array($section,$allowed),404);$data=['section'=>$section,'orders'=>auth()->user()->orders()->latest()->get(),'addresses'=>auth()->user()->addresses,'wishlist'=>auth()->user()->wishlistItems()->with('product')->latest()->get(),'rewards'=>auth()->user()->rewards()->latest()->get(),'returns'=>ReturnRequest::where('user_id',auth()->id())->with('order')->latest()->get()];return view('account.section',$data);} public function profile(Request $r){$d=$r->validate(['name'=>'required|max:120','phone'=>'nullable|max:40']);auth()->user()->update($d);return back()->with('success','Profile updated.');} public function addressStore(Request $r){$d=$r->validate(['label'=>'required|max:40','name'=>'required|max:120','phone'=>'nullable|max:40','line1'=>'required|max:180','line2'=>'nullable|max:180','city'=>'required|max:120','county'=>'nullable|max:120','postcode'=>'nullable|max:30','country'=>'required|size:2','is_default'=>'nullable|boolean']);if($r->boolean('is_default'))auth()->user()->addresses()->update(['is_default'=>false]);auth()->user()->addresses()->create($d+['is_default'=>$r->boolean('is_default')]);return back()->with('success','Address saved.');} public function addressDelete(Address $address){abort_unless($address->user_id===auth()->id(),403);$address->delete();return back()->with('success','Address removed.');} public function returnStore(Request $r,Order $order){abort_unless($order->user_id===auth()->id(),403);$d=$r->validate(['type'=>'required|in:return,exchange','reason'=>'required|max:150','details'=>'nullable|max:2000']);ReturnRequest::create($d+['user_id'=>auth()->id(),'order_id'=>$order->id,'number'=>'RET-'.strtoupper(Str::random(8))]);return back()->with('success','Return/exchange request submitted.');} public function invoice(Order $order){abort_unless($order->user_id===auth()->id(),403);$order->load('items');return view('account.invoice',compact('order'));}}
